<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Since AI 2026 — Live Board</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&family=JetBrains+Mono:wght@500;700&display=swap" rel="stylesheet">
<style>
:root{--bg:#0b0d12;--card:#141823;--line:#232a3a;--fg:#e8ecf4;--mut:#8a93a8;--acc:#7cf29c;--warn:#ffb547;--red:#ff6b6b;--blue:#6aa8ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 Inter,system-ui,sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:24px 18px 60px}
header{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:8px}
h1{margin:0;font-size:22px;font-weight:800}h1 span{color:var(--acc)}
.clock{font:700 20px 'JetBrains Mono',monospace;color:var(--mut)}.clock b{color:var(--fg)}
.hero{margin:20px 0;padding:26px;border-radius:16px;background:linear-gradient(135deg,#142a1d,#141823 60%);border:1px solid var(--line)}
.hero .lbl{color:var(--mut);text-transform:uppercase;letter-spacing:.12em;font-size:12px}
.hero .what{font-size:22px;font-weight:700;margin:4px 0 10px}
.cd{font:700 clamp(36px,8vw,72px)/1 'JetBrains Mono',monospace;color:var(--acc)}
.cd small{font-size:.35em;color:var(--mut);margin:0 10px 0 2px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px}
.card h2{margin:0 0 12px;font-size:13px;text-transform:uppercase;letter-spacing:.12em;color:var(--mut)}
.ev{display:flex;gap:12px;padding:8px 0;border-top:1px solid var(--line)}.ev:first-of-type{border-top:0}
.ev .tm{font:600 13px 'JetBrains Mono',monospace;color:var(--blue);min-width:92px}
.ev .tt{font-weight:600}.ev .lc{color:var(--mut);font-size:13px}
.ev.past{opacity:.35}.ev.now{background:#16301f;margin:0 -10px;padding:8px 10px;border-radius:8px}
.ev.now .tm{color:var(--acc)}.ev.dl .tt{color:var(--warn)}
.pill{display:inline-block;font-size:11px;font-weight:700;padding:1px 7px;border-radius:99px;margin-left:6px;vertical-align:2px}
.p-now{background:var(--acc);color:#000}.p-dl{background:var(--warn);color:#000}
.day{font-weight:800;margin:18px 0 4px;font-size:16px}
label.ck{display:flex;gap:10px;padding:7px 0;border-top:1px solid var(--line);cursor:pointer;align-items:flex-start}
label.ck:first-of-type{border-top:0}label.ck input{margin-top:4px;accent-color:var(--acc)}
label.ck.done span{text-decoration:line-through;color:var(--mut)}
.ck small{color:var(--mut);display:block}
.bar{height:8px;background:var(--line);border-radius:99px;overflow:hidden;margin:4px 0 14px}.bar i{display:block;height:100%;background:var(--acc)}
a{color:var(--blue)}.links a{display:inline-block;margin:0 14px 6px 0}
.tag{font-size:11px;color:var(--mut);border:1px solid var(--line);border-radius:6px;padding:0 6px;margin-left:6px}
</style></head><body><div class="wrap">
<header><h1>Since AI <span>2026</span> · Live Board</h1><div class="clock">Turku <b id="clk">--:--:--</b></div></header>

<section class="hero"><div class="lbl" id="hlbl">Next milestone</div><div class="what" id="hwhat"></div><div class="cd" id="hcd"></div><div class="lc" id="hwhen" style="color:var(--mut);margin-top:8px"></div></section>

<div class="grid">
 <div class="card"><h2>Happening now</h2><div id="now"></div></div>
 <div class="card"><h2>Up next</h2><div id="next"></div></div>
</div>

<div class="grid" style="margin-top:16px">
 <div class="card"><h2>Claim before Friday</h2><div class="bar"><i id="b1"></i></div><div id="claim"></div></div>
 <div class="card"><h2>Team prep checklist</h2><div class="bar"><i id="b2"></i></div><div id="prep"></div></div>
</div>

<div class="card" style="margin-top:16px"><h2>Full schedule</h2><div id="sched"></div></div>

<div class="card links" style="margin-top:16px"><h2>Links</h2>
<a href="https://sinceai.app">sinceai.app</a><a href="https://sinceai.ai/hackathon-2026/guide/builders">Builder Guide</a><a href="https://sinceai.ai/hackathon-2026/guide">Field Guide</a><a href="https://sinceai.ai/hackathon-2026/guide#ai-resources">AI tools &amp; LUMI</a><a href="https://sinceai.ai/hackathon-2026/guide/venue">Venue / maps</a>
<div style="color:var(--mut);font-size:13px;margin-top:6px">Help: info@sinceai.fi · Checkboxes are saved in this browser only.</div></div>
</div>
<script>
const EV=__EVENTS__;
const DL=/deadline|closes|summaries open|start building|registration opens|finals:/i;
const CLAIM=[
 ["Featherless AI — $25 credit","Open-weight model API, no card · every participant · claim early"],
 ["Google AI Pro + AI Studio $10/mo","Students, via MLH · Gemini API for the project"],
 ["Google Cloud $300 trial","New accounts · 90 days · GPUs / hosting fallback"],
 ["GitHub Copilot Student","Verified students"],
 ["Lovable Pro (1 month)","Fast frontend if we need a UI quickly"],
 ["ElevenLabs Creator (1 month)","Only if voice/audio might be in scope"],
 ["n8n Cloud Pro — ONE per team","Agents/automation · pick one person to claim"],
 ["Pruna AI shared key","Image/video API · shared team key in the guide"],
 ["Red Hat OpenShift Developer Sandbox","Optional: only if going for the Red Hat award"],
];
const PREP=[
 ["Everyone has own sinceai.app account + is in the SAME team","Team formation closes Fri 16:45"],
 ["Agree who is team lead","Lead marks ready + selects challenge Fri 15:00–17:30"],
 ["Read all 15 challenge summaries, shortlist ≥3","Thu 15:00 · places are first come first served"],
 ["Join the Since AI Discord",""],
 ["Attendance confirmed on dashboard",""],
 ["make setup on every laptop + make keys passes","GPU torch, API keys"],
 ["make models — download models at home","Venue Wi-Fi is shared"],
 ["GitHub repo ready, everyone can push","Commit 'Pre-event boilerplate' on Friday"],
 ["VPS + domain ready for demo URL","make deploy"],
 ["LUMI access approved?","If not by Thu → email info@sinceai.fi"],
 ["YouTube account ready for demo video","Unlisted link · < 2 min · show it working in first 20 s"],
 ["Pack: laptop, charger, EU adapter, bottle, pen, hotspot",""],
 ["Accommodation booked (if sleeping)","SINCEAI2026 code: Omena −15%, Caribia −20%"],
];
const $=id=>document.getElementById(id);
const fmtT=d=>d.toLocaleTimeString('en-GB',{timeZone:'Europe/Helsinki',hour:'2-digit',minute:'2-digit'});
const fmtD=d=>d.toLocaleDateString('en-GB',{timeZone:'Europe/Helsinki',weekday:'long',day:'numeric',month:'short'});
EV.forEach(e=>{e.S=new Date(e.s);e.E=e.e?new Date(e.e):null;e.dl=DL.test(e.t)});
function store(k,v){try{if(v===undefined)return JSON.parse(localStorage.getItem(k)||'{}');localStorage.setItem(k,JSON.stringify(v))}catch(_){return{}}}
function checklist(el,bar,items,key){const st=store(key);el.innerHTML='';items.forEach(([t,s],i)=>{const l=document.createElement('label');l.className='ck'+(st[i]?' done':'');l.innerHTML=`<input type="checkbox" ${st[i]?'checked':''}><span>${t}<small>${s}</small></span>`;l.querySelector('input').onchange=ev=>{st[i]=ev.target.checked;store(key,st);checklist(el,bar,items,key)};el.appendChild(l)});$(bar).style.width=(100*Object.values(st).filter(Boolean).length/items.length)+'%'}
function row(e,now){const cur=e.E?(e.S<=now&&now<e.E):false,past=(e.E||e.S)<now&&!cur;const tm=fmtT(e.S)+(e.E?'–'+fmtT(e.E):'');return `<div class="ev ${past?'past':''} ${cur?'now':''} ${e.dl?'dl':''}"><div class="tm">${tm}</div><div><div class="tt">${e.t}${cur?'<span class="pill p-now">NOW</span>':''}${e.dl&&!past?'<span class="pill p-dl">KEY</span>':''}</div><div class="lc">${e.l}</div></div></div>`}
function cdStr(ms){const s=Math.max(0,ms/1000|0),d=s/86400|0,h=s%86400/3600|0,m=s%3600/60|0,x=s%60,p=n=>String(n).padStart(2,'0');return (d?`${d}<small>d</small>`:'')+`${p(h)}<small>h</small>${p(m)}<small>m</small>${p(x)}<small>s</small>`}
let lastMin=-1;
function tick(){const now=new Date();$('clk').textContent=now.toLocaleTimeString('en-GB',{timeZone:'Europe/Helsinki'});
 const nk=EV.find(e=>e.dl&&e.S>now);
 if(nk){$('hwhat').textContent=nk.t;$('hcd').innerHTML=cdStr(nk.S-now);$('hwhen').textContent=fmtD(nk.S)+' · '+fmtT(nk.S)+' · '+nk.l}
 else{$('hlbl').textContent='';$('hwhat').textContent='That\'s a wrap. Well built.';$('hcd').textContent=''}
 if(now.getMinutes()!==lastMin){lastMin=now.getMinutes();render(now)}}
function render(now){
 const cur=EV.filter(e=>e.E&&e.S<=now&&now<e.E);$('now').innerHTML=cur.length?cur.map(e=>row(e,now)).join(''):'<div class="lc" style="color:var(--mut)">Nothing scheduled right now — keep building.</div>';
 $('next').innerHTML=EV.filter(e=>e.S>now).slice(0,5).map(e=>row(e,now)).join('')||'<div style="color:var(--mut)">All done.</div>';
 let h='',day='';EV.forEach(e=>{const d=fmtD(e.S);if(d!==day){day=d;h+=`<div class="day">${d}</div>`}h+=row(e,now)});$('sched').innerHTML=h}
checklist($('claim'),'b1',CLAIM,'sai-claim');checklist($('prep'),'b2',PREP,'sai-prep');tick();setInterval(tick,1000);
</script></body></html>
EOF
python3 - <<EOF
s=open("$S/tpl.html").read().replace("__EVENTS__",open("$S/events.json").read().strip())
open("/data/dev/sinceAI_hackathon/docs/live.html","w").write(s)
EOF
