<style>body{margin:0;background:#0b0e14;color:#e8ecf4;font:15px/1.45 system-ui}main{max-width:1000px;margin:auto;padding:18px}h1{font-size:21px;margin:0 0 4px}p{margin:4px 0 12px;color:#aab3c5}
canvas{width:100%;display:block;border-radius:10px;cursor:crosshair;image-rendering:auto}.r{display:flex;flex-wrap:wrap;gap:16px;align-items:center;margin:12px 0}
