<div id="st"></div><p style="margin-top:12px"><small>Real wave equations (2D FDTD) running live in your browser at 3.5 GHz, 2 m × 1 m. Waves are 8.6 cm long. It's a teaching demo: a flat slice with perfectly reflecting buildings and made-up power levels, so the colours and warning are illustrative, not a real interference assessment.</small></p></main>
<script>
const f=3.5e9,lam=3e8/f,dx=lam/14,NX=Math.round(2/dx),NY=Math.round(1/dx),S=.5,T=lam/dx/S,PM=20;
const c=document.getElementById('c');c.width=NX;c.height=NY;const g=c.getContext('2d');const im=g.createImageData(NX,NY);
const N=NX*NY,id=(i,j)=>i+NX*j,I=m=>Math.round(m/dx),W=new Uint8Array(N),D=new Float32Array(N);
function box(x0,x1,h){for(let i=I(x0);i<I(x1);i++)for(let j=0;j<I(h);j++)W[id(i,j)]=1}
