for(let i=0;i<NX;i++)for(let j=0;j<NY;j++){const a=Math.max(0,(PM-i)/PM,(i-(NX-1-PM))/PM),b=Math.max(0,(j-(NY-1-PM))/PM);D[id(i,j)]=1-.16*Math.min(1,a*a+b*b)}
function mk(){return{E:new Float32Array(N),X:new Float32Array(N),Y:new Float32Array(N),P:0,n:0}}
let A=mk(),B=mk(),mx=I(.3),my=I(.62);const rx=I(1.3),ry=I(.08),ri=id(rx,ry);
function step(o,src){const{E,X,Y}=o;
 for(let j=0;j<NY-1;j++)for(let i=0;i<NX;i++){const k=i+NX*j;X[k]-=S*(E[k+NX]-E[k])}
 for(let j=0;j<NY;j++)for(let i=0;i<NX-1;i++){const k=i+NX*j;Y[k]+=S*(E[k+1]-E[k])}
 for(let j=1;j<NY;j++)for(let i=1;i<NX;i++){const k=i+NX*j;E[k]+=S*((Y[k]-Y[k-1])-(X[k]-X[k-NX]))}
 const s=Math.sin(2*Math.PI*o.n/T)*Math.min(1,o.n/60);src(E,s);
 for(let k=0;k<N;k++){if(W[k]){E[k]=0}else{E[k]*=D[k];X[k]*=D[k];Y[k]*=D[k]}}
 o.P+=(E[ri]*E[ri]-o.P)*.006;o.n++}
const satSrc=(E,s)=>{const j=NY-PM-3;for(let i=PM;i<NX-PM;i++)E[i+NX*j]+=.06*s};
const mastSrc=(E,s)=>{E[mx+NX*my]+=s};
