c.onclick=e=>{const r=c.getBoundingClientRect(),i=Math.floor((e.clientX-r.left)/r.width*NX),j=NY-1-Math.floor((e.clientY-r.top)/r.height*NY);if(i>PM&&i<NX-PM&&j<NY-PM&&!W[id(i,j)]){mx=i;my=j;B=mk()}};
$('r').onclick=()=>{A=mk();B=mk()};
function col(v){v=Math.max(-1,Math.min(1,v));return v>0?[245-v*140,245-v*215,245-v*225]:[245+v*185,245+v*110,245+v*50]}
