 for(let j=0;j<NY;j++)for(let i=0;i<NX;i++){const q=i+NX*j,o=4*(i+NX*(NY-1-j));let C;if(W[q])C=[42,46,61];else C=col((sa*A.E[q]+ma*B.E[q])/.3);d[o]=C[0];d[o+1]=C[1];d[o+2]=C[2];d[o+3]=255}
 g.putImageData(im,0,0);g.fillStyle='#1ec85a';g.fillRect(rx-4,NY-1-ry-4,9,9);g.fillStyle='#ffbe00';g.fillRect(mx-4,NY-1-my-4,9,9);
 if(!sa){st.textContent='Satellite signal off: nothing for the dish to receive.';st.style.background='#222a3a';return}
 if(!ma||A.n<500||B.n<500){st.textContent=ma?'Measuring at the dish…':'Mast off: the dish only hears the satellite.';st.style.background='#222a3a';return}
 const db=10*Math.log10((ma*ma*B.P+1e-12)/(A.P+1e-12));const a=db>0?['#b3261e','HIGH: the mast is stronger than the satellite signal at the dish.']:db>-10?['#b26a00','MEDIUM: the mast is noticeable at the dish.']:['#14713a','LOW: the dish is mostly protected.'];st.style.background=a[0];st.textContent=`${a[1]} Mast vs satellite at dish: ${db>0?'+':''}${db.toFixed(0)} dB`}
function fr(){for(let n=0;n<3;n++){step(A,satSrc);step(B,mastSrc)}const p=+$('p').value/100;draw(p*p*4);requestAnimationFrame(fr)}
fr();
</script></body></html>
